class Registry
  def initialize
    @registered = []
    @registered_ids = {}
  end

  def register(obj)
    id = obj.object_id

    return self if @registered_ids.key?(id)

    @registered << obj
    @registered_ids[id] = true
    self
  end

  def registered?(obj)
    @registered_ids.key?(obj.object_id)
  end

  def size
    @registered.size
  end

  def to_a
    @registered.dup
  end
end
