class Counter
  attr_reader :value

  def initialize
    @value = 0
    @step = 1
  end

  def bump
    @value += @step
    self
  end

  def with_step(step)
    previous_step = @step
    @step = step
    yield
  ensure
    @step = previous_step
  end

  private

  def initialize_copy(original)
    super
    @value = original.value
    @step = 1
  end
end
