class KeyStore
  def initialize
    @entries = {}
  end

  def store(key, value)
    @entries[key] = value
  end

  def fetch(key)
    if @entries.key?(key)
      @entries[key]
    elsif block_given?
      yield
    end
  end

  protected

  def key_stored?(key)
    @entries.key?(key)
  end
end

class TallyingKeyStore < KeyStore
  attr_reader :hits, :misses

  def initialize
    super
    @hits = 0
    @misses = 0
  end

  def fetch(key)
    if key_stored?(key)
      @hits += 1
    else
      @misses += 1
    end

    super
  end
end
