class KeyStore
  def initialize
    @store = {}
  end

  def store(key, value)
    @store[key] = value
  end

  def fetch(key, &block)
    if @store.key?(key)
      @store[key]
    elsif block
      block.call
    else
      nil
    end
  end
end

class TallyingKeyStore < KeyStore
  attr_reader :hits, :misses

  def initialize
    super
    @hits = 0
    @misses = 0
  end

  def fetch(key, &block)
    if @store.key?(key)
      @hits += 1
    else
      @misses += 1
    end

    super(key, &block)
  end
end
