require "bigdecimal"

class ExpenseTracker
  class NearestCent
    def round(amount)
      BigDecimal(amount.to_s).round(2)
    end
  end

  def initialize(rounding: NearestCent.new)
    @rounding = rounding
    @records = []
  end

  def record(amount)
    @records << @rounding.round(amount)
    self
  end

  def total
    @records.sum
  end

  def initialize_copy(other)
    super
    @records = other.instance_variable_get(:@records).dup
  end
end
